import matplotlib.pyplot as plt

def PlotData(data, labels):
    iterations, notes = data
    if len(iterations) != len(notes):
        raise ValueError("Lengths of iterations and notes must be the same")
    
    if len(iterations[0]) != len(labels):
        raise ValueError("Number of labels must match the number of datasets")
    
    for i, note in enumerate(notes):
        plt.plot(iterations[i], note, marker='.', markersize=10, linestyle='solid', label=labels[i])

    plt.xlabel('Iterations')
    plt.ylabel('Notes')
    plt.legend()
    plt.show()

# Assuming 'iterations' and 'notes' are defined correctly
# Assuming 'legend' is defined correctly with labels for each dataset

PlotData((iterations, notes), legend)

# Call the function with the new iteration steps and updated notes
PlotData((iterations, notes), legend)



